-- Durable queue: every user mutation and its delivery intent commit together.
CREATE TABLE native_sync_control (singleton INTEGER PRIMARY KEY CHECK(singleton=1), cursor TEXT NOT NULL DEFAULT '0', applying INTEGER NOT NULL DEFAULT 0 CHECK(applying IN (0,1)), last_success TEXT);
CREATE TABLE native_sync_meta(entity_table TEXT NOT NULL, id TEXT NOT NULL, revision TEXT, remote_updated_at TEXT, PRIMARY KEY(entity_table,id));
CREATE TABLE native_sync_outbox(seq INTEGER PRIMARY KEY AUTOINCREMENT, operation_id TEXT NOT NULL UNIQUE DEFAULT(lower(printf('%s-%s-%s-%s-%s',hex(randomblob(4)),hex(randomblob(2)),hex(randomblob(2)),hex(randomblob(2)),hex(randomblob(6))))), entity_table TEXT NOT NULL, id TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('put','delete')), payload TEXT, base_revision TEXT, base_updated_at TEXT);
CREATE INDEX native_sync_outbox_entity ON native_sync_outbox(entity_table,id,seq);
CREATE TABLE native_sync_conflicts(entity_table TEXT NOT NULL, id TEXT NOT NULL, remote TEXT NOT NULL, PRIMARY KEY(entity_table,id));
CREATE TRIGGER sync_projects_insert AFTER INSERT ON projects WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_projects_update AFTER UPDATE ON projects WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_projects_delete AFTER DELETE ON projects WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_tasks_insert AFTER INSERT ON tasks WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_tasks_update AFTER UPDATE ON tasks WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_tasks_delete AFTER DELETE ON tasks WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_notes_insert AFTER INSERT ON notes WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_notes_update AFTER UPDATE ON notes WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_notes_delete AFTER DELETE ON notes WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_events_insert AFTER INSERT ON events WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_events_update AFTER UPDATE ON events WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_events_delete AFTER DELETE ON events WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_library_items_insert AFTER INSERT ON library_items WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_library_items_update AFTER UPDATE ON library_items WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_library_items_delete AFTER DELETE ON library_items WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_inbox_items_insert AFTER INSERT ON inbox_items WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_inbox_items_update AFTER UPDATE ON inbox_items WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_inbox_items_delete AFTER DELETE ON inbox_items WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
CREATE TRIGGER sync_settings_update AFTER UPDATE ON workspace_settings WHEN (SELECT applying FROM native_sync_control)=0 BEGIN
